 const shared=Boolean(syncState?.access),viewer=shared&&!syncState?.access?.editKey,unresolved=Boolean(syncState?.pending||syncState?.creation),writeBlocked=shared?Boolean(syncState&&cloudLocked(syncState)):conflict||unresolved||Boolean(syncLoadError);
 if(shared&&!syncState?.room)return <div className="ump-load"><Users size={32}/><h1>{viewer?'正在打开观赛链接':'正在连接共享比赛'}</h1><p>{syncState?.error||'正在获取云端的最新比分，请稍候。'}</p><button className="ump-btn ump-primary" disabled={syncState?.busy||syncState?.externalConflict} onClick={()=>void retryShared()}><RefreshCw size={18}/>重新连接</button>{syncState?.externalConflict&&<button className="ump-btn" onClick={()=>location.reload()}>重新载入页面</button>}<button className="ump-btn" disabled={unresolved||syncState?.busy} onClick={leaveShared}>返回本机比赛</button></div>;
